input.command:
python3 -c "
import json
with open('/root/DATA/products/PersonalizeForce.json') as f:
    data = json.load(f)
if isinstance(data, list):
    print('Type: list, Length:', len(data))
    print('First item keys:', list(data[0].keys()) if data else 'empty')
    print('First item (truncated):')
    print(json.dumps(data[0], indent=2)[:3000])
elif isinstance(data, dict):
    print('Type: dict, Keys:', list(data.keys()))
    for k in list(data.keys())[:5]:
        v = data[k]
        if isinstance(v, str):
            print(f'{k}: {v[:200]}')
        elif isinstance(v, list):
            print(f'{k}: list of {len(v)} items')
        elif isinstance(v, dict):
            print(f'{k}: dict with keys {list(v.keys())[:10]}')
"

